function mapFields(kind){const candidates={image:['image_id','image','image_code','image_id_a','image_id_b','image_a','image_b','left_image_id','right_image_id'],worker:['worker_id','worker','worker_a','worker_b','worker_id_a','worker_id_b'],object:['object_id','inventory_record_id','record_id','object_id_a','object_id_b']}[kind];const mapped=S.meta?.field_map?.[kind];return [...new Set([...(Array.isArray(mapped)?mapped:mapped?[mapped]:[]),...candidates])].filter(c=>fieldIndex(c)>=0);}
