function filterMatch(row,f){const v=row[S.ci[f.field]];switch(f.op){case'eq':return !missing(v)&&String(v)===f.value;case'contains':return !missing(v)&&display(v).toLowerCase().includes(f.value.toLowerCase());case'range':return number(v)&&(f.min===null||v>=f.min)&&(f.max===null||v<=f.max);case'missing':return missing(v);case'present':return !missing(v);default:return true;}}
