function renderFilterChips(){const labels={eq:'=',contains:'包含',range:'∈',missing:'缺失',present:'非缺失'};$('filterChips').innerHTML=S.filters.map((f,i)=>`<span class="filter-chip">${esc(f.field)} ${labels[f.op]} ${esc(f.op==='range'?`[${f.min??'−∞'}, ${f.max??'+∞'}]`:f.value||'')}<button data-remove-filter="${i}" aria-label="删除此筛选">×</button></span>`).join('')+Object.entries(S.global).filter(([,v])=>v).map(([k,v])=>`<span class="filter-chip global-chip">跨表 ${esc(k)} = ${esc(v)}${mapFields(k).length?'':' · 本表未应用'}</span>`).join('');}
