function addFilter(){const field=$('filterField').value,op=$('filterOperator').value,value=$('filterValue').value;const f={field,op,value};$('filterMessage').textContent='';if(op==='range'){const min=$('filterValue').value.trim(),max=$('filterMax').value.trim();f.min=min===''?null:Number(min);f.max=max===''?null:Number(max);if((f.min!==null&&!Number.isFinite(f.min))||(f.max!==null&&!Number.isFinite(f.max))||(f.min!==null&&f.max!==null&&f.min>f.max)){ $('filterMessage').textContent='请输入有效的数值区间，最小值不能大于最大值。';return;}}else if((op==='eq'||op==='contains')&&value===''){$('filterMessage').textContent='请输入筛选值；要查空值，请选择“缺失”。';return;}S.filters.push(f);S.page=1;applyFilters();}
