function exportCsv(){const csvCell=v=>{let s=missing(v)?'':display(v);if(typeof v==='string'&&/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const rows=[S.cols,...S.filtered.map(i=>S.rows[i])].map(r=>r.map(csvCell).join(',')).join('\r\n');download(`${S.meta.id}__filtered_${S.filtered.length}.csv`,'\uFEFF'+rows,'text/csv;charset=utf-8');toast(`已导出 ${fmt(S.filtered.length)} 条筛选记录，保留完整数值精度`);}
